const cards=[...document.querySelectorAll('.card')];let filter='all';const search=document.querySelector('#search');function update(){let n=0;const q=search.value.trim().toLocaleLowerCase();cards.forEach(c=>{const show=(filter==='all'||c.dataset.genre===filter)&&c.dataset.title.toLocaleLowerCase().includes(q);c.hidden=!show;if(show)n++;});document.querySelector('#empty').hidden=n!==0;document.querySelector('#count').textContent=`${n}개의 공략집 예시`;}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});update();}));search.addEventListener('input',update);
